-- TASK-031: 乌东来源资料的本机演示目录。
-- 所有新增商业内容均为 demo_data=TRUE、verification_status=UNVERIFIED；金额与容量只用于本机流程。
-- V5 通用占位行仅前向下架，不物理删除，以便公开目录精确展示本批来源内容并保留历史记录。

UPDATE product
SET catalog_status = 'UNPUBLISHED', version = version + 1
WHERE id = '40000000-0000-0000-0000-000000000001' AND catalog_status = 'PUBLISHED';

UPDATE food_item
SET catalog_status = 'UNPUBLISHED', version = version + 1
WHERE id IN (
  '41000000-0000-0000-0000-000000000001',
  '41000000-0000-0000-0000-000000000002',
  '41000000-0000-0000-0000-000000000003'
) AND catalog_status = 'PUBLISHED';

UPDATE stay_property
SET catalog_status = 'UNPUBLISHED', version = version + 1
WHERE id = '42000000-0000-0000-0000-000000000001' AND catalog_status = 'PUBLISHED';

UPDATE room_type
SET catalog_status = 'UNPUBLISHED', version = version + 1
WHERE id = '42100000-0000-0000-0000-000000000001' AND catalog_status = 'PUBLISHED';

UPDATE place
SET catalog_status = 'UNPUBLISHED', version = version + 1
WHERE id IN (
  '43000000-0000-0000-0000-000000000001',
  '43000000-0000-0000-0000-000000000003'
) AND catalog_status = 'PUBLISHED';

UPDATE community_post
SET published = FALSE
WHERE id IN (
  '20000000-0000-0000-0000-000000000001',
  '20000000-0000-0000-0000-000000000002'
) AND published = TRUE;

