INSERT INTO community_post (
  id, visitor_id, account_id, title, content, author_name, cover_url, tags, post_type, route_summary, route_nodes_json, demo_data, legacy_data, published, published_at
)
VALUES
  ('45000000-0000-0000-0000-000000000101', NULL, NULL, '乌东苗寨：山地聚落与村寨日常', '乌东苗寨沿雷公山山地展开，溪流、吊脚楼与公共空间构成村寨日常的阅读线索；茶叶、天麻等生计和苗年、吃新节等传统也见于资料记录。资料整理/演示，以现场为准；不同时点的统计数字不作为当前事实。', '乌东平台演示资料', '/images/wudong-content/image193.jpg', '乌东苗寨,山地聚落,村寨生活,演示资料', 'MOMENT', NULL, JSON_ARRAY(), TRUE, TRUE, TRUE, '2026-09-11 09:04:00'),
  ('45000000-0000-0000-0000-000000000102', NULL, NULL, '苗族银饰锻制技艺', '苗族银饰锻制是资料记录的地方工艺主题，乌东及周边村落保留银饰制作与传承活动。资料整理/演示，以现场为准；传承人数量、材质与产业数据需另行核验。', '乌东平台演示资料', '/images/wudong-content/image194.jpg', '苗族银饰,锻制技艺,非遗,演示资料', 'MOMENT', NULL, JSON_ARRAY(), TRUE, TRUE, TRUE, '2026-09-11 09:05:00'),
  ('45000000-0000-0000-0000-000000000103', NULL, NULL, '苗族刺绣与织锦：纹样和针法', '苗绣与织锦以破线绣、平绣等技法表现花鸟、龙凤等纹样，资料也记录当地工坊参与技艺传承。资料整理/演示，以现场为准；具体作品、作者与纹样含义需另行核验。', '乌东平台演示资料', '/images/wudong-content/image196.jpg', '苗族刺绣,织锦,传统纹样,非遗,演示资料', 'MOMENT', NULL, JSON_ARRAY(), TRUE, TRUE, TRUE, '2026-09-11 09:06:00'),
  ('45000000-0000-0000-0000-000000000104', NULL, NULL, '苗年与吃新节：节庆中的歌舞与丰收', '苗年资料记录祭祖、拦门歌、芦笙舞、游方等环节；吃新节围绕丰收，并保留各村寨不同做法。资料整理/演示，以现场为准；不同年份活动安排不作为固定演出承诺。', '乌东平台演示资料', '/images/wudong-content/image201.jpg', '苗年,吃新节,芦笙舞,节庆文化,演示资料', 'MOMENT', NULL, JSON_ARRAY(), TRUE, TRUE, TRUE, '2026-09-11 09:07:00');
